#include <iostream>
using namespace std;

using ull = unsigned long long;
using u128 = unsigned __int128;

ull mod;

ull mulMod(ull a, ull b) {
    return static_cast<ull>((u128)a * b % mod);
}

ull powMod(ull a, ull e) {
    ull result = 1 % mod;
    a %= mod;
    while (e) {
        if (e & 1) result = mulMod(result, a);
        a = mulMod(a, a);
        e >>= 1;
    }
    return result;
}

struct Matrix {
    ull a[3][3]{};
};

Matrix multiply(const Matrix& x, const Matrix& y) {
    Matrix z;
    for (int i = 0; i < 3; ++i) {
        for (int k = 0; k < 3; ++k) {
            for (int j = 0; j < 3; ++j) {
                ull term = mulMod(x.a[i][k], y.a[k][j]);
                z.a[i][j] = static_cast<ull>(
                    ((u128)z.a[i][j] + term) % mod
                );
            }
        }
    }
    return z;
}

Matrix matrixPower(Matrix base, ull exponent) {
    Matrix result;
    for (int i = 0; i < 3; ++i) result.a[i][i] = 1 % mod;

    while (exponent) {
        if (exponent & 1) result = multiply(result, base);
        base = multiply(base, base);
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull n, k, l;
    cin >> n >> k >> l >> mod;

    if (mod == 1) {
        cout << 0 << '\n';
        return 0;
    }

    ull s0;

    if (n == 2) {
        s0 = 1 % mod;
    } else if (n == 3) {
        s0 = 3 % mod;
    } else {
        Matrix transition;
        transition.a[0][0] = 1 % mod;
        transition.a[0][1] = 1 % mod;
        transition.a[0][2] = 2 % mod;
        transition.a[1][0] = 1 % mod;
        transition.a[2][2] = 2 % mod;

        Matrix power = matrixPower(transition, n - 3);
        ull initial[3] = {3 % mod, 1 % mod, 2 % mod};

        s0 = 0;
        for (int i = 0; i < 3; ++i) {
            ull term = mulMod(power.a[0][i], initial[i]);
            s0 = static_cast<ull>(((u128)s0 + term) % mod);
        }
    }

    ull total = powMod(2, n);
    ull s1 = total >= s0 ? total - s0 : mod - (s0 - total);

    if (l < 64 && k >= (1ULL << l)) {
        cout << 0 << '\n';
        return 0;
    }

    ull ones = static_cast<ull>(__builtin_popcountll(k));
    ull result = mulMod(powMod(s0, ones), powMod(s1, l - ones));

    cout << result << '\n';
    return 0;
}

