pair<ull, ull> fibonacci(ull n) {
    if (n == 0) return {0, 1 % mod};

    auto [a, b] = fibonacci(n >> 1);

    ull twoBMinusA = static_cast<ull>(((u128)2 * b + mod - a) % mod);
    ull c = mulMod(a, twoBMinusA);
    ull d = static_cast<ull>(((u128)mulMod(a, a) + mulMod(b, b)) % mod);

    if (n & 1)
        return {d, static_cast<ull>(((u128)c + d) % mod)};
    return {c, d};
}

